{"command": "mkdir -p /workspace/work && cd /workspace/work && cat > sg.py << 'PYEOF'
import numpy as np, base64
SR = 33452.0          # FT2 C-4 base 8363 * 4
F0 = SR/128.0         # 261.34375 -> "C-4" reference for power-of-2 tables

def relnote_for(L, cycles=1):
    """relNote so that C-4 plays the looped table (L samples, `cycles` cycles) at F0."""
    return int(round(12*np.log2(F0*L/(8363.0*cycles))))

def to_i16(x):
    x = np.asarray(x, dtype=float)
    m = np.abs(x).max()
    if m > 1e-9: x = x/m
    return np.clip(x*32000, -32768, 32767).astype('<i2')

def b64(a):
    return base64.b64encode(np.asarray(a, dtype='<i2').tobytes()).decode()

def phasor(n, k=1):
    """saw, k cycles over n samples, phase-continuous at 0"""
    t = np.arange(n)/n*k
    return 2.0*(t - np.floor(t+0.5))

def square(n, k=1, duty=0.5):
    t = np.arange(n)/n*k
    return np.where((t % 1.0) < duty, 1.0, -1.0)

def bandlimit(shape_fn, n, k=1, maxh=None):
    """Build a band-limited waveform via additive harmonics with per-harmonic weight."""
    out = np.zeros(n)
    t = np.arange(n)
    H = maxh if maxh is not None else n//(2*k)
    for h in range(1, H+1):
        w = shape_fn(h)
        if abs(w) < 1e-6: continue
        out += w*np.sin(2*np.pi*h*k*t/n + 0.0)
    return out
